import{graphicPages,activeGraphicPageId}from'./pages';import{exportDocumentSvg}from'./fabric-adapter';import{crc32}from'./raster-source';import{MAX_PROJECT_BYTES}from'./project-limits';import type{GraphicDocument}from'./model';
interface ZipEntry{name:string;bytes:Uint8Array;}
/** Stored ZIP with UTF-8 paths generated by the editor, no dependency or compression worker. */
export function pageZip(entries:readonly ZipEntry[]):Uint8Array<ArrayBuffer>{
 if(!entries.length||entries.length>100)throw Error('Numero file di esportazione non valido');const encode=new TextEncoder(),files=entries.map(entry=>{if(!/^pagina-\d{3}\.svg$/.test(entry.name))throw Error('Nome file di pagina non valido');return{...entry,nameBytes:encode.encode(entry.name),crc:crc32(entry.bytes)};}),size=files.reduce((n,file)=>n+file.bytes.byteLength+file.nameBytes.length*2+76,22);if(size>MAX_PROJECT_BYTES)throw Error('Esportazione SVG oltre 120 MB: esporta le singole pagine.');const output=new Uint8Array(size),view=new DataView(output.buffer),central:{file:typeof files[number];offset:number}[]=[];let at=0;
 const u16=(value:number)=>{view.setUint16(at,value,true);at+=2;},u32=(value:number)=>{view.setUint32(at,value,true);at+=4;},put=(bytes:Uint8Array)=>{output.set(bytes,at);at+=bytes.length;};
 for(const file of files){central.push({file,offset:at});u32(0x04034b50);u16(20);u16(0x800);u16(0);u16(0);u16(33);u32(file.crc);u32(file.bytes.length);u32(file.bytes.length);u16(file.nameBytes.length);u16(0);put(file.nameBytes);put(file.bytes);}
 const start=at;for(const{file,offset}of central){u32(0x02014b50);u16(20);u16(20);u16(0x800);u16(0);u16(0);u16(33);u32(file.crc);u32(file.bytes.length);u32(file.bytes.length);u16(file.nameBytes.length);u16(0);u16(0);u16(0);u16(0);u32(0);u32(offset);put(file.nameBytes);}const length=at-start;u32(0x06054b50);u16(0);u16(0);u16(files.length);u16(files.length);u32(length);u32(start);u16(0);if(at!==size)throw Error('Archivio SVG non coerente');return output;
}
export async function exportProjectSvgZip(document:GraphicDocument):Promise<Uint8Array<ArrayBuffer>>{
 const entries:ZipEntry[]=[];let bytes=0;for(const[index,page]of graphicPages(document).entries()){const svg=await exportDocumentSvg(page),data=new TextEncoder().encode(svg);bytes+=data.length;if(bytes>MAX_PROJECT_BYTES)throw Error('Esportazione SVG oltre 120 MB: esporta le singole pagine.');entries.push({name:`pagina-${String(index+1).padStart(3,'0')}.svg`,bytes:data});}return pageZip(entries);
}
export function currentPageName(document:GraphicDocument):string{const pages=graphicPages(document),index=pages.findIndex(page=>activeGraphicPageId(page)===activeGraphicPageId(document));return`pagina-${String(index+1).padStart(3,'0')}`;}
